  const wf = (fields) => ({ id:'p', entry:'start', nodes:[
    { id:'start', type:'trigger', next:'f' },
    { id:'f', type:'form', next:'end', schema:{ fields } },
    { id:'end', type:'end', result:'ok' },
  ]});
  // element type mismatch: Uint8 elements are numbers; field says string
  let r = m.executeWorkflow(wf([{ path:'samples.1', type:'string' }]), { samples:new Uint8Array([1,2]) });
  console.log('TA elem wrong type:', r.status, JSON.stringify(r.errors||''));
  // element range: integer with min
  r = m.executeWorkflow(wf([{ path:'samples.1', type:'integer', min:5 }]), { samples:new Uint8Array([1,2]) });
  console.log('TA elem range fail:', r.status, JSON.stringify(r.errors||''));
  r = m.executeWorkflow(wf([{ path:'samples.1', type:'integer', min:2 }]), { samples:new Uint8Array([1,2]) });
  console.log('TA elem range ok:', r.status, JSON.stringify(r.errors||''));
  // existing element cannot be replaced by default even if matching
  r = m.executeWorkflow(wf([{ path:'samples.1', type:'integer', default:99 }]), { samples:new Uint8Array([1,2]) });
  console.log('TA elem default kept:', r.status, JSON.stringify(r.errors||''), 'samples[1]:', r.context.input.samples[1]);
  // nested non-index field on typed array with created parent
  r = m.executeWorkflow(wf([{ path:'samples.meta.who', type:'string', default:'me' }]), { samples:new Uint8Array([1,2]) });
  console.log('TA named nested:', r.status, JSON.stringify(r.errors||''), 'meta:', JSON.stringify(r.context.input.samples.meta));
  // named prop intermediate existing holding primitive -> type error
  r = m.executeWorkflow(wf([{ path:'samples.tag.sub', type:'string', default:'x' }]), Object.assign(new Uint8Array([1,2]), { tag: 5 }));
  console.log('TA named primitive parent:', r.status, JSON.stringify(r.errors||''));
});
"

