    reserve: (input, output, nodeId, attempt) => {
      reserveSeen.push({ bytes: [...input.samples], tag: input.samples.tag, earlier: structuredClone(input.earlier), nodeId, attempt });
      return { id: 'tx-7' };
    },
    release: (input, output, returned, nodeId, attempt) => {
